# MAGIC %md
# MAGIC ## 0. Setup
# MAGIC Free Edition normally has a catalog called `workspace`. If yours is different, change `CATALOG`.

# COMMAND ----------

CATALOG = "workspace"
SCHEMA = "imas_demo"
VOLUME = "raw"
T = f"{CATALOG}.{SCHEMA}"
RAW = f"/Volumes/{CATALOG}/{SCHEMA}/{VOLUME}"

spark.sql(f"CREATE SCHEMA IF NOT EXISTS {T}")
spark.sql(f"CREATE VOLUME IF NOT EXISTS {T}.{VOLUME}")
print("Raw files folder:", RAW)

# COMMAND ----------

# MAGIC %md
# MAGIC ## 1. Generate dummy source files (deliberately messy, like real exports)

# COMMAND ----------

import random
import numpy as np
import pandas as pd

random.seed(42)
np.random.seed(42)

first_m = ["Ahmad", "Muhammad", "Hafiz", "Danial", "Irfan", "Zikri", "Aiman", "Haziq", "Adam", "Yusuf", "Imran", "Farhan"]
first_f = ["Nur", "Aisyah", "Sofea", "Alya", "Balqis", "Husna", "Nadia", "Aina", "Safiya", "Maryam", "Qistina", "Iman"]
last = ["Rahman", "Ismail", "Abdullah", "Hassan", "Karim", "Salleh", "Omar", "Yahya", "Ibrahim", "Zainal"]

# ---- ERP export: student master -------------------------------------------
per_grade = [52, 50, 48, 47, 46, 45, 44, 42, 38]          # 412 students
rows, sid = [], 2000
for g, n in enumerate(per_grade, start=1):
    for _ in range(n):
        sid += 1
        male = random.random() < 0.52
        name = f"{random.choice(first_m if male else first_f)} {random.choice(last)}"
        year = random.choices([2021, 2022, 2023, 2024, 2025], weights=[14, 16, 19, 21, 30])[0]
        d = pd.Timestamp(year=year, month=random.choice([1, 1, 1, 2, 7, 8]), day=random.randint(1, 28))
        rows.append({
            "student_id": f"S{sid}",
            "student_name": name,
            "grade_raw": random.choice([f"Grade {g}", f"grade {g}", f"G{g}", f"Gred {g}"]),
            "gender_raw": random.choice(["Male", "M", "L"] if male else ["Female", "F", "P"]) if random.random() > 0.02 else None,
            "enrol_date_raw": d.strftime(random.choice(["%d/%m/%Y", "%Y-%m-%d"])),
        })
erp = pd.DataFrame(rows)
# Excel class allocation: class name = grade number + A/B
class_list = pd.DataFrame({
    "student_id": erp["student_id"],
    "class_name": [f"{int(''.join(ch for ch in g if ch.isdigit()))}{random.choice('AB')}" for g in erp["grade_raw"]],
})
# add duplicates with messy spacing/casing (re-exports happen in real life)
dups = erp.sample(15, random_state=1).copy()
dups["student_name"] = dups["student_name"].str.upper() + " "
erp = pd.concat([erp, dups], ignore_index=True)
erp.to_csv(f"{RAW}/erp_students.csv", index=False)

# ---- Excel file: class allocation -----------------------------------------
class_list.to_csv(f"{RAW}/excel_class_list.csv", index=False)

# ---- Google Drive sheet: teachers -----------------------------------------
depts = {"Arabic": 9, "Islamic Studies": 8, "English": 8, "Mathematics": 7, "Science": 7, "Others": 7}
trows, tid = [], 100
for dname, n in depts.items():
    for _ in range(n):
        tid += 1
        male = random.random() < 0.45
        trows.append({
            "teacher_id": f"T{tid}",
            "teacher_name": f"{random.choice(first_m if male else first_f)} {random.choice(last)}",
            "department": random.choice([dname, dname.upper(), dname.lower() + " "]),
            "join_date": pd.Timestamp(year=random.randint(2015, 2025), month=random.randint(1, 12), day=random.randint(1, 28)).strftime("%d-%m-%Y"),
        })
pd.DataFrame(trows).to_csv(f"{RAW}/gdrive_teachers.csv", index=False)

# ---- EasyStore export: bookstore orders -----------------------------------
cats = {"Islamic Studies": 28, "Arabic": 32, "Mathematics": 35, "Science": 38, "English": 30, "Others": 22}
catalog = [(f"{c[:3].upper()}-G{g}", f"{c} Textbook - Grade {g}", c, g, p) for c, p in cats.items() for g in range(1, 10)]
month_w = [58, 25, 11, 8, 9, 8, 22, 13, 9, 7, 5, 12]       # busy at start of the school year
orows = []
for i in range(1904):
    sku, title, cat, g, price = random.choice(catalog)
    m = random.choices(range(1, 13), weights=month_w)[0]
    d = pd.Timestamp(year=2025, month=m, day=random.randint(1, 28))
    qty = random.choices([1, 2, 3, 4], weights=[45, 35, 15, 5])[0]
    orows.append({
        "order_id": f"ES-{10001 + i}",
        "order_date_raw": d.strftime("%Y-%m-%d"),
        "sku": sku, "title": title, "category": cat, "grade": g,
        "qty_raw": qty if random.random() > 0.01 else None,
        "unit_price_raw": random.choice([f"{price:.2f}", f"RM {price:.2f}"]),
    })
sales = pd.DataFrame(orows)
sales = pd.concat([sales, sales.sample(12, random_state=2)], ignore_index=True)   # duplicate orders
sales.to_csv(f"{RAW}/easystore_orders.csv", index=False)

print(dbutils.fs.ls(RAW))

# COMMAND ----------

# MAGIC %md
# MAGIC ## 2. BRONZE: load raw files exactly as received (all text) and add lineage columns

# COMMAND ----------

from pyspark.sql import functions as F

sources = {
    "bronze_students": "erp_students.csv",
    "bronze_classes": "excel_class_list.csv",
    "bronze_teachers": "gdrive_teachers.csv",
    "bronze_sales": "easystore_orders.csv",
}
for table, file in sources.items():
    df = (spark.read.option("header", True).option("inferSchema", False).csv(f"{RAW}/{file}")
          .withColumn("source_file", F.col("_metadata.file_path"))
          .withColumn("ingested_at", F.current_timestamp()))
    df.write.mode("overwrite").option("overwriteSchema", True).saveAsTable(f"{T}.{table}")
    print(table, df.count(), "rows")

# COMMAND ----------

# MAGIC %md
# MAGIC ## 3. SILVER: clean and standardise with Python / Pandas

# COMMAND ----------

def save(pdf, name):
    spark.createDataFrame(pdf).write.mode("overwrite").option("overwriteSchema", True).saveAsTable(f"{T}.{name}")
    print(name, len(pdf), "rows")

# ---- students ----
s = spark.table(f"{T}.bronze_students").toPandas()
n_in = len(s)
s["student_name"] = s["student_name"].str.strip().str.title()
s["grade"] = s["grade_raw"].str.extract(r"(\d+)")[0].astype(int)
gmap = {"m": "Male", "male": "Male", "l": "Male", "f": "Female", "female": "Female", "p": "Female"}
s["gender"] = s["gender_raw"].str.strip().str.lower().map(gmap).fillna("Unknown")
s["enrol_date"] = pd.to_datetime(s["enrol_date_raw"], format="mixed", dayfirst=True, errors="coerce")
s["enrol_year"] = s["enrol_date"].dt.year
s = s.sort_values("ingested_at").drop_duplicates("student_id", keep="last")           # rule: one row per student_id
c = spark.table(f"{T}.bronze_classes").toPandas().drop_duplicates("student_id")[["student_id", "class_name"]]
s = s.merge(c, on="student_id", how="left")
save(s[["student_id", "student_name", "grade", "gender", "class_name", "enrol_date", "enrol_year"]], "silver_students")
print("duplicates removed:", n_in - len(s))

# ---- teachers ----
t = spark.table(f"{T}.bronze_teachers").toPandas()
t["teacher_name"] = t["teacher_name"].str.strip().str.title()
t["department"] = t["department"].str.strip().str.title()
t["join_date"] = pd.to_datetime(t["join_date"], format="%d-%m-%Y", errors="coerce")
save(t[["teacher_id", "teacher_name", "department", "join_date"]].drop_duplicates("teacher_id"), "silver_teachers")

# ---- sales ----
o = spark.table(f"{T}.bronze_sales").toPandas()
n_in = len(o)
o = o.drop_duplicates("order_id")                                                     # rule: one row per order
o = o[o["qty_raw"].notna()].copy()                                                    # rule: drop rows with missing quantity
o["qty"] = o["qty_raw"].astype(float).astype(int)
o["unit_price"] = o["unit_price_raw"].str.replace("RM", "", regex=False).str.strip().astype(float)
o["order_date"] = pd.to_datetime(o["order_date_raw"])
o["grade"] = o["grade"].astype(int)
o["revenue"] = (o["qty"] * o["unit_price"]).round(2)
save(o[["order_id", "order_date", "sku", "title", "category", "grade", "qty", "unit_price", "revenue"]], "silver_sales")
print("rows removed:", n_in - len(o))

# COMMAND ----------

# MAGIC %md
# MAGIC ## 4. GOLD: business-ready tables that the dashboard reads

# COMMAND ----------

gold = {
"gold_kpi_overview": f"""
  SELECT (SELECT COUNT(*) FROM {T}.silver_students) AS total_students,
         (SELECT COUNT(*) FROM {T}.silver_teachers) AS total_teachers,
         ROUND((SELECT COUNT(*) FROM {T}.silver_students) / (SELECT COUNT(*) FROM {T}.silver_teachers), 1) AS student_teacher_ratio,
         (SELECT COUNT(*) FROM {T}.silver_students WHERE enrol_year = 2025) AS new_enrolments""",
"gold_students_by_grade": f"""
  SELECT CONCAT('Grade ', grade) AS grade_label, grade, COUNT(*) AS students
  FROM {T}.silver_students GROUP BY grade ORDER BY grade""",
"gold_students_by_gender": f"""
  SELECT gender, COUNT(*) AS students FROM {T}.silver_students GROUP BY gender""",
"gold_enrolment_by_year": f"""
  SELECT enrol_year, COUNT(*) AS new_students FROM {T}.silver_students GROUP BY enrol_year ORDER BY enrol_year""",
"gold_teachers_by_department": f"""
  SELECT department, COUNT(*) AS teachers FROM {T}.silver_teachers GROUP BY department ORDER BY teachers DESC""",
"gold_class_summary": f"""
  SELECT CONCAT('Grade ', grade) AS grade_label, grade, COUNT(DISTINCT class_name) AS classes,
         COUNT(*) AS students, ROUND(COUNT(*) / COUNT(DISTINCT class_name), 1) AS avg_class_size
  FROM {T}.silver_students GROUP BY grade ORDER BY grade""",
"gold_kpi_sales": f"""
  SELECT ROUND(SUM(revenue), 2) AS total_sales, SUM(qty) AS units_sold, COUNT(DISTINCT order_id) AS orders,
         ROUND(SUM(revenue) / COUNT(DISTINCT order_id), 2) AS avg_order_value
  FROM {T}.silver_sales""",
"gold_sales_monthly": f"""
  SELECT MONTH(order_date) AS month_no, DATE_FORMAT(order_date, 'MMM') AS month,
         SUM(qty) AS units, ROUND(SUM(revenue), 2) AS sales
  FROM {T}.silver_sales GROUP BY 1, 2 ORDER BY 1""",
"gold_sales_by_category": f"""
  SELECT category, ROUND(SUM(revenue), 2) AS sales FROM {T}.silver_sales GROUP BY category ORDER BY sales DESC""",
"gold_top_titles": f"""
  SELECT title, SUM(qty) AS units FROM {T}.silver_sales GROUP BY title ORDER BY units DESC LIMIT 5""",
"gold_sales_by_grade": f"""
  SELECT CONCAT('Grade ', grade) AS grade_label, grade, SUM(qty) AS units, ROUND(SUM(revenue), 2) AS sales
  FROM {T}.silver_sales GROUP BY grade ORDER BY grade""",
}
for name, query in gold.items():
    spark.sql(f"CREATE OR REPLACE TABLE {T}.{name} AS {query}")
    print("built", name)

# COMMAND ----------

# MAGIC %md
# MAGIC ## 5. Quick check (row counts per layer)

# COMMAND ----------

for tbl in ["bronze_students", "silver_students", "bronze_teachers", "silver_teachers", "bronze_sales", "silver_sales"]:
    print(f"{tbl:20s}", spark.table(f"{T}.{tbl}").count())
display(spark.table(f"{T}.gold_kpi_overview"))
display(spark.table(f"{T}.gold_kpi_sales"))

# COMMAND ----------

